<?php
declare(strict_types=1);
namespace TempNumber;
interface PaymentAdapter {public function create(array $payment):array;public function verify(string $reference):array;}
final class StripeCheckout implements PaymentAdapter {
 private function request(string $method,string $path,array $data=[],?string $key=null):array {if(!env('STRIPE_SECRET_KEY'))fail('PAYMENT_UNAVAILABLE','Hosted checkout is not configured.',503);$base=env('APP_ENV')==='testing'?env('STRIPE_TEST_API_URL','https://api.stripe.com/v1'):'https://api.stripe.com/v1';$c=curl_init($base.'/'.$path);if(env('CURL_CA_BUNDLE'))curl_setopt($c,CURLOPT_CAINFO,env('CURL_CA_BUNDLE'));$headers=['Authorization: Bearer '.env('STRIPE_SECRET_KEY')];if($key)$headers[]='Idempotency-Key: '.$key;curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>20,CURLOPT_HTTPHEADER=>$headers,CURLOPT_FOLLOWLOCATION=>false]);if($method==='POST'){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,http_build_query($data));}$raw=curl_exec($c);$status=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);if($raw===false||$status<200||$status>=300)fail('PAYMENT_UNAVAILABLE','Payment confirmation is temporarily unavailable. Your payment remains pending.',503);$v=json_decode($raw,true);if(!is_array($v))fail('PAYMENT_UNAVAILABLE','Payment response could not be verified.',503);return $v;}
 public function create(array $payment):array {return $this->request('POST','checkout/sessions',['mode'=>'payment','customer_email'=>$payment['customer_email']??null,'client_reference_id'=>$payment['id'],'metadata'=>['payment_id'=>$payment['id'],'user_id'=>$payment['user_id']],'line_items'=>[['price_data'=>['currency'=>'usd','product_data'=>['name'=>'Boostlier wallet top-up'],'unit_amount'=>(int)$payment['amount_cents']],'quantity'=>1]],'success_url'=>env('APP_URL').'/payment/return?reference='.$payment['id'],'cancel_url'=>env('APP_URL').'/dashboard/wallet?checkout=cancelled','adaptive_pricing'=>['enabled'=>'false']],'topup:'.$payment['id']);}
 public function verify(string $reference):array {return $this->request('GET','checkout/sessions/'.rawurlencode($reference));}
 public static function webhook(string $raw,string $signature):array {if(!env('STRIPE_WEBHOOK_SECRET'))fail('PAYMENT_UNAVAILABLE','Webhook verification is not configured.',503);$parts=[];foreach(explode(',',$signature)as$part){$pair=explode('=',$part,2);if(count($pair)===2)$parts[$pair[0]][]=$pair[1];}$t=$parts['t'][0]??'';if(!ctype_digit($t)||abs(time()-(int)$t)>300)fail('INVALID_SIGNATURE','Invalid webhook signature.',400);$expected=hash_hmac('sha256',$t.'.'.$raw,env('STRIPE_WEBHOOK_SECRET'));$valid=false;foreach($parts['v1']??[]as$s)$valid=$valid||hash_equals($expected,$s);if(!$valid)fail('INVALID_SIGNATURE','Invalid webhook signature.',400);$event=json_decode($raw,true);if(!is_array($event))fail('INVALID_JSON','Invalid webhook.',400);return $event;}
}
require_once __DIR__.'/Flutterwave.php';
require_once __DIR__.'/StripeFunding.php';
final class Payments {
 public static function options():array {
  $options=Flutterwave::options();$providers=[];
  if(StripeFunding::enabled())$providers[]=['id'=>'stripe','name'=>'Card (Stripe)','test_mode'=>str_starts_with(env('STRIPE_SECRET_KEY'),'sk_test_')];
  if($options['enabled'])$providers[]=['id'=>'flutterwave','name'=>'Local payment (Flutterwave)','test_mode'=>str_contains(env('FLW_SECRET_KEY'),'TEST')];
  $options['providers']=$providers;$options['provider']=$providers[0]['id']??'stripe';$options['enabled']=(bool)$providers;return $options;
 }
 public static function quote(array $u,array $b):array {
  $provider=$b['provider']??self::options()['provider'];
  if($provider==='stripe')return StripeFunding::quote($u,$b);
  if($provider==='flutterwave')return Flutterwave::quote($u,$b)+['provider'=>'flutterwave'];
  fail('INVALID_PROVIDER','Choose an available payment method.');
 }
 public static function create(array $u,array $data):array {
  if(!self::options()['enabled'])fail('PAYMENT_UNAVAILABLE','Wallet funding is not configured.',503);
  $quote=required($data,'quote_id',32);$q=one('SELECT provider FROM funding_quotes WHERE id=? AND user_id=?',[$quote,$u['id']]);if(!$q)fail('NOT_FOUND','Funding quote not found.',404);
  return $q['provider']==='stripe'?StripeFunding::checkout($u,$data):Flutterwave::checkout($u,$data);
 }
 public static function verify(string $id,?string $owner=null):array {$p=one('SELECT * FROM payments WHERE id=?',[$id]);if(!$p||($owner!==null&&$p['user_id']!==$owner))fail('NOT_FOUND','Payment not found.',404);if($p['status']==='currency_review')fail('CURRENCY_REVIEW_REQUIRED','An earlier checkout needs manual review. Start a new USD checkout.',409);if($p['status']==='successful')return ['status'=>'successful','reference'=>$id];if(!$p['provider_reference']){if($p['provider']==='stripe'&&$p['status']==='pending')StripeFunding::open($p);return ['status'=>'pending','reference'=>$id];}if($p['provider']==='flutterwave')return Flutterwave::verify($p);$s=(new StripeCheckout())->verify($p['provider_reference']);return self::credit($id,$s);}
 public static function credit(string $id,array $s):array {return tx(function()use($id,$s){$p=one('SELECT * FROM payments WHERE id=?'.lockSuffix(),[$id]);if(!$p)fail('NOT_FOUND','Payment not found.',404);if($p['status']==='currency_review')fail('CURRENCY_REVIEW_REQUIRED','An earlier checkout needs manual review before it can be credited.',409);$expected=($p['status']==='successful'&&!empty($p['original_currency']))?strtolower($p['original_currency']):'usd';if((isset($s['mode'])&&$s['mode']!=='payment')||(isset($s['livemode'])&&$s['livemode']!==str_starts_with(env('STRIPE_SECRET_KEY'),'sk_live_'))||$p['provider']!=='stripe'||($s['metadata']['payment_id']??'')!==$id||($s['metadata']['user_id']??'')!==$p['user_id']||($s['client_reference_id']??'')!==$id||($p['provider_reference']!==null&&$s['id']!==$p['provider_reference'])||($s['currency']??'')!==$expected||($s['amount_total']??null)!==(int)$p['amount_cents'])fail('PAYMENT_MISMATCH','The payment details could not be matched.',409);if(($s['payment_status']??'')!=='paid'){if(($s['status']??'')==='expired'&&$p['status']==='pending'){query("UPDATE payments SET status='failed',updated_at=? WHERE id=?",[now(),$id]);return ['status'=>'failed','reference'=>$id];}return ['status'=>$p['status']==='successful'?'successful':'pending','reference'=>$id];}if($p['status']==='successful'&&$expected!=='usd')return ['status'=>'successful','reference'=>$id];$credited=Wallet::change($p['user_id'],'topup',(int)$p['amount_cents'],'topup:'.$id,'Verified Stripe USD top-up');if($credited)audit('stripe_payment_verified',$p['user_id'],['payment_id'=>$id,'session_id'=>$s['id']]);query("UPDATE payments SET provider_reference=?,status='successful',updated_at=? WHERE id=?",[$s['id'],now(),$id]);return ['status'=>'successful','reference'=>$id];});}
}
